import{_ as t,l as d,o as a,c as i,v as o,p as l,x as s,d as c,i as n,S as E}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"FUSE","description":"","frontmatter":{"title":"FUSE","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fuse.md","filePath":"cs/fuse.md","lastUpdated":1789023840000}'),f={name:"cs/fuse.md"};function u(p,e,S,h,F,_){const r=d("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="fuse" tabindex="-1">FUSE <a class="header-anchor" href="#fuse" aria-label="Permalink to &quot;FUSE&quot;">​</a></h1><div class="epigraph"><p>FUSE 把 VFS 操作编成发往用户守护进程的请求；真正的 lookup/read 在用户态完成，再把结果填回内核页缓存。</p><footer>—— 据 Szeredi, FUSE；Linux fuse 文档；Vangoor, Tarasov, Zadok 对 FUSE 性能的测量</footer></div><p><a href="/cs/overlayfs">上一课</a>仍在内核里叠两棵内核 FS。<a href="/cs/vfs">VFS</a> 的操作表也可以指向一个<strong>把请求送出内核</strong>的驱动。缺口是 FUSE：让 sshfs、ntfs-3g、用户态实验 FS 不必进内核树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核实现新 FS 要模块、许可证、崩溃半径。FUSE：内核模块登记 fuse 超级块；用户守护进程通过 <code>/dev/fuse</code> 读请求、写应答。read 可能两次拷贝（内核到守护、守护到内核页）。缺口：请求类型（lookup、open、read、write、setattr）、多线程守护、以及 <code>cache_readdir</code> 与内核 <a href="/cs/dcache">dcache</a> / <a href="/cs/page-cache">页缓存</a> 如何可选地缓存用户态结果。</p><p><span class="marginnote">deadlock：守护进程自己再访问同一挂载点会卡住。解决方案是克隆线程、或 <code>fuse_conn</code> 的 abort。本课不写 libfuse API 教程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户 <code>open</code>：VFS → fuse → 队列 → 守护 <code>open</code> 回调 → 返回句柄。<code>read</code>：内核或可把请求与页一起交给守护，守护填缓冲，内核插入页树。写路径类似，fsync 变成用户态 fsync。对照 overlay：联合可以在用户态做（unionfs-fuse），慢但可实验。对照内核 ext4：没有系统调用往返。</p>',8)),(a(),l(E,null,{default:s(()=>[n(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYS%5B%22%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%5D%20--%3E%20VFS%5B%22VFS%22%5D%0A%20%20VFS%20--%3E%20DEV%5B%22%2Fdev%2Ffuse%20%E8%AF%B7%E6%B1%82%22%5D%0A%20%20DEV%20--%3E%20DAEM%5B%22%E7%94%A8%E6%88%B7%E5%AE%88%E6%8A%A4%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20DAEM%20--%3E%20DEV%0A%20%20DEV%20--%3E%20PAGE%5B%22%E5%8F%AF%E9%80%89%E5%A1%AB%E9%A1%B5%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>FUSE 把文件系统变成普通进程：可用脚本语言、可调试、崩溃不带倒内核（挂载点会 I/O 错误）。税是上下文切换与拷贝。不要把 FUSE 写成数据库用户态存储引擎综述：接口仍是 POSIX 文件，不是 SQL。</p><p>安全：挂载通常允许用户在自己的目录上 <code>fusermount</code>，节点由 MNT_NOSUID 等限制；这是策略，对象仍是请求协议。</p><p>实现上：FUSE 的 daemon 若单线程且再访问同一挂载点，会自死锁。内核可 abort 连接把等待者唤醒为 ENODEV。writeback 缓存开启时语义更像本地 FS，关闭则更像严格 RPC。 读法上只引用<a href="/cs/overlayfs">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>FUSE</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 virtio-fs、fuse-bpf 的全部加速路径。不保证与 <a href="/cs/lsm-selinux">SELinux</a> 标签透传的每一种组合。下一课把「文件在另一台机器」的语义裂缝钉住：NFS 的缓存与关闭-打开一致性。</p><p>版本字段会变，课序钉的是机制对象「FUSE」，不是某一主线内核的结构体名。 后课默认：VFS 操作可以出核。远程文件语义与本地 POSIX 差在哪，下一课 NFS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FUSE 用 <code>/dev/fuse</code> 把 VFS 请求交给用户态。</li><li>可缓存进 dcache/页缓存，默认仍有往返税。</li><li>远程语义是下一课。</li><li>出处：Linux fuse 文档；Vangoor et al. 对 FUSE 性能；Szeredi。</li></ul>',11))])}const B=t(f,[["render",u]]);export{m as __pageData,B as default};
